commands.stdout:
/dts-v1/;

/ {
	compatible = "nextthing,pocketchip", "nextthing,chip", "allwinner,sun5i-r8", "allwinner,sun5i-a13";
	serial-number = "162542170e0288c0";
	model = "NextThing PocketC.H.I.P.";
	interrupt-parent = <0x01>;
	#address-cells = <0x01>;
	#size-cells = <0x01>;

	reserved-memory {
		ranges;
		#address-cells = <0x01>;
		#size-cells = <0x01>;

		default-pool {
			reusable;
			compatible = "shared-dma-pool";
			alloc-ranges = <0x40000000 0x10000000>;
			size = <0x6000000>;
			linux,cma-default;
		};
	};

	pwrseq {
		compatible = "mmc-pwrseq-simple";
		reset-gpios = <0x12 0x02 0x13 0x01>;
		phandle = <0x0f>;
	};

	clocks {
		ranges;
		#address-cells = <0x01>;
		#size-cells = <0x01>;

		clk-24M {
			compatible = "fixed-clock";
			#clock-cells = <0x00>;
			phandle = <0x17>;
			clock-output-names = "osc24M";
			clock-frequency = <0x16e3600>;
		};

		clk-32k {
			compatible = "fixed-clock";
			#clock-cells = <0x00>;
			phandle = <0x18>;
			clock-output-names = "osc32k";
			clock-frequency = <0x8000>;
		};
	};

	usb2-vbus {
		compatible = "regulator-fixed";
		regulator-boot-on;
		enable-active-high;
		gpio = <0x12 0x07 0x03 0x00>;
		status = "disabled";
		phandle = <0x68>;
		regulator-min-microvolt = <0x4c4b40>;
		regulator-max-microvolt = <0x4c4b40>;
		regulator-name = "usb2-vbus";
	};

	display-engine {
		compatible = "allwinner,sun5i-a13-display-engine";
		allwinner,pipelines = <0x27>;
	};

	__symbols__ {
		pwm = "/soc/pwm@1c20e00";
		reg_usb1_vbus = "/usb1-vbus";
		mdio = "/soc/mdio@1c0b080";
		uart2_pd_pins = "/soc/pinctrl@1c20800/uart2-pd-pins";
		reg_ahci_5v = "/ahci-5v";
		reg_ldo2 = "/soc/i2c@1c2ac00/pmic@34/regulators/ldo2";
		gpu_opp_table = "/opp-table-gpu";
		intc = "/soc/interrupt-controller@1c20400";
		spi2 = "/soc/spi@1c17000";
		mmc0_pwrseq = "/pwrseq";
		i2c1 = "/soc/i2c@1c2b000";
		tve0 = "/soc/tv-encoder@1c0a000";
		panel_input = "/panel/port/endpoint";
		mali = "/soc/gpu@1c40000";
		ve_sram = "/soc/system-control@1c00000/sram@1d00000/sram-section@0";
		nand_pins = "/soc/pinctrl@1c20800/nand-pins";
		reg_usb0_vbus = "/usb0-vbus";
		spi0 = "/soc/spi@1c05000";
		cpu_alert0 = "/thermal-zones/cpu-thermal/trips/cpu-alert0";
		reg_vcc3v0 = "/vcc3v0";
		tcon0_in = "/soc/lcd-controller@1c0c000/ports/port@0";
		ohci0 = "/soc/usb@1c14400";
		mmc1 = "/soc/mmc@1c10000";
		reg_dcdc3 = "/soc/i2c@1c2ac00/pmic@34/regulators/dcdc3";
		mmc2_8bit_pins = "/soc/pinctrl@1c20800/mmc2-8bit-pins";
		lcd_rgb666_pins = "/soc/pinctrl@1c20800/lcd-rgb666-pins";
		uart2_cts_rts_pd_pins = "/soc/pinctrl@1c20800/uart2-cts-rts-pd-pins";
		rtp = "/soc/rtp@1c25000";
		nand_rb0_pin = "/soc/pinctrl@1c20800/nand-rb0-pin";
		uart1_pg_pins = "/soc/pinctrl@1c20800/uart1-pg-pins";
		dma = "/soc/dma-controller@1c02000";
		fe0_out = "/soc/display-frontend@1e00000/ports/port@1";
		tcon0_out_tve0 = "/soc/lcd-controller@1c0c000/ports/port@1/endpoint@1";
		ccu = "/soc/clock@1c20000";
		otg_sram = "/soc/system-control@1c00000/sram@10000/sram-section@0";
		usb_otg = "/soc/usb@1c13000";
