		reg_ldo3 = "/soc/i2c@1c2ac00/pmic@34/regulators/ldo3";
		uart0 = "/soc/serial@1c28000";
		i2c1_pins = "/soc/pinctrl@1c20800/i2c1-pins";
		sram_a = "/soc/system-control@1c00000/sram@0";
		osc24M = "/clocks/clk-24M";
		reg_vcc3v3 = "/vcc3v3";
