		wdt = "/soc/watchdog@1c20c90";
		lcd_rgb565_pins = "/soc/pinctrl@1c20800/lcd-rgb565-pins";
		tcon0_out = "/soc/lcd-controller@1c0c000/ports/port@1";
		i2c2 = "/soc/i2c@1c2b400";
		reg_vcc5v0 = "/vcc5v0";
		uart1_pe_pins = "/soc/pinctrl@1c20800/uart1-pe-pins";
		reg_ldo1 = "/soc/i2c@1c2ac00/pmic@34/regulators/ldo1";
		ehci0 = "/soc/usb@1c14000";
		spi1 = "/soc/spi@1c06000";
		osc32k = "/clocks/clk-32k";
		fe0_out_be0 = "/soc/display-frontend@1e00000/ports/port@1/endpoint";
		i2c0 = "/soc/i2c@1c2ac00";
		mmc2 = "/soc/mmc@1c11000";
		i2c0_pins = "/soc/pinctrl@1c20800/i2c0-pins";
		nand_cs0_pin = "/soc/pinctrl@1c20800/nand-cs0-pin";
		ir0 = "/soc/ir@1c21800";
		axp_adc = "/soc/i2c@1c2ac00/pmic@34/adc";
		tcon0_in_be0 = "/soc/lcd-controller@1c0c000/ports/port@0/endpoint";
		be0_out_tcon0 = "/soc/display-backend@1e60000/ports/port@1/endpoint";
		be0 = "/soc/display-backend@1e60000";
		lradc = "/soc/lradc@1c22800";
		mmc0 = "/soc/mmc@1c0f000";
		reg_dcdc2 = "/soc/i2c@1c2ac00/pmic@34/regulators/dcdc2";
		codec = "/soc/codec@1c22c00";
		spi2_pe_pins = "/soc/pinctrl@1c20800/spi2-pe-pins";
		emac = "/soc/ethernet@1c0b000";
		spi2_cs0_pe_pin = "/soc/pinctrl@1c20800/spi2-cs0-pe-pin";
		crypto = "/soc/crypto-engine@1c15000";
		pwm0_pin = "/soc/pinctrl@1c20800/pwm0-pin";
		mmc2_4bit_pc_pins = "/soc/pinctrl@1c20800/mmc2-4bit-pc-pins";
		ir0_rx_pin = "/soc/pinctrl@1c20800/ir0-rx-pin";
		pio = "/soc/pinctrl@1c20800";
		reg_usb2_vbus = "/usb2-vbus";
		uart3 = "/soc/serial@1c28c00";
		uart3_pg_pins = "/soc/pinctrl@1c20800/uart3-pg-pins";
		sram_d = "/soc/system-control@1c00000/sram@10000";
		usb_power_supply = "/soc/i2c@1c2ac00/pmic@34/usb-power";
		ac_power_supply = "/soc/i2c@1c2ac00/pmic@34/ac-power";
		axp209 = "/soc/i2c@1c2ac00/pmic@34";
		be0_out = "/soc/display-backend@1e60000/ports/port@1";
		keyboard = "/soc/i2c@1c2b000/keyboard@34";
		backlight = "/backlight";
		cpu_crit = "/thermal-zones/cpu-thermal/trips/cpu-crit";
		tcon0_out_panel = "/soc/lcd-controller@1c0c000/ports/port@1/endpoint@0";
		mbus = "/soc/dram-controller@1c01000";
		reg_ldo4 = "/soc/i2c@1c2ac00/pmic@34/regulators/ldo4";
		uart1 = "/soc/serial@1c28400";
		sid = "/soc/eeprom@1c23800";
		battery_power_supply = "/soc/i2c@1c2ac00/pmic@34/battery-power";
		cpu0 = "/cpus/cpu@0";
		tve0_in_tcon0 = "/soc/tv-encoder@1c0a000/port/endpoint";
	};

	usb1-vbus {
		compatible = "regulator-fixed";
		regulator-boot-on;
		enable-active-high;
		gpio = <0x12 0x07 0x06 0x00>;
		status = "disabled";
		phandle = <0x67>;
		regulator-min-microvolt = <0x4c4b40>;
		regulator-max-microvolt = <0x4c4b40>;
		regulator-name = "usb1-vbus";
	};

	soc {
		compatible = "simple-bus";
		ranges;
		#address-cells = <0x01>;
		#size-cells = <0x01>;
		dma-ranges;

		spi@1c06000 {
			compatible = "allwinner,sun4i-a10-spi";
			clocks = <0x02 0x25 0x02 0x46>;
			clock-names = "ahb", "mod";
			status = "disabled";
			#address-cells = <0x01>;
			interrupts = <0x0b>;
			#size-cells = <0x00>;
			dma-names = "rx", "tx";
			phandle = <0x2e>;
			reg = <0x1c06000 0x1000>;
			dmas = <0x04 0x01 0x09 0x04 0x01 0x08>;
		};

		serial@1c28000 {
			reg-io-width = <0x04>;
			compatible = "snps,dw-apb-uart";
			clocks = <0x02 0x3b>;
			status = "disabled";
			interrupts = <0x01>;
			phandle = <0x4e>;
			reg = <0x1c28000 0x400>;
			reg-shift = <0x02>;
		};

		watchdog@1c20c90 {
			compatible = "allwinner,sun4i-a10-wdt";
			clocks = <0x17>;
			interrupts = <0x18>;
			phandle = <0x49>;
			reg = <0x1c20c90 0x10>;
		};

		pwm@1c20e00 {
			compatible = "allwinner,sun5i-a13-pwm";
			clocks = <0x02 0x01>;
			status = "okay";
			phandle = <0x64>;
			reg = <0x1c20e00 0x0c>;
			pinctrl-0 = <0x44>;
			#pwm-cells = <0x03>;
			pinctrl-names = "default";
		};

		lcd-controller@1c0c000 {
			compatible = "allwinner,sun5i-a13-tcon";
			clocks = <0x02 0x2b 0x02 0x5a 0x02 0x5c>;
			resets = <0x02 0x06>;
			clock-names = "ahb", "tcon-ch0", "tcon-ch1";
			status = "okay";
			interrupts = <0x2c>;
			#clock-cells = <0x00>;
			phandle = <0x32>;
			reg = <0x1c0c000 0x1000>;
			clock-output-names = "tcon-data-clock";
			pinctrl-0 = <0x3f>;
			dmas = <0x04 0x01 0x0e>;
			reset-names = "lcd";
			pinctrl-names = "default";

			ports {
				#address-cells = <0x01>;
				#size-cells = <0x00>;

				port@1 {
					#address-cells = <0x01>;
					#size-cells = <0x00>;
					phandle = <0x34>;
					reg = <0x01>;

					endpoint@1 {
						remote-endpoint = <0x00>;
						allwinner,tcon-channel = <0x01>;
						status = "disabled";
						phandle = <0x08>;
						reg = <0x01>;
					};

					endpoint@0 {
						remote-endpoint = <0x6d>;
						phandle = <0x6c>;
						reg = <0x00>;
					};
				};

				port@0 {
					phandle = <0x33>;
					reg = <0x00>;

					endpoint {
						remote-endpoint = <0x0a>;
						phandle = <0x23>;
					};
				};
			};
		};

		mmc@1c0f000 {
			compatible = "allwinner,sun5i-a13-mmc";
			clocks = <0x02 0x1d 0x02 0x40>;
			clock-names = "ahb", "mmc";
			status = "okay";
			#address-cells = <0x01>;
			interrupts = <0x20>;
			bus-width = <0x01>;
			#size-cells = <0x00>;
			phandle = <0x35>;
			reg = <0x1c0f000 0x1000>;
			pinctrl-0 = <0x0d>;
			vmmc-supply = <0x0e>;
			mmc-pwrseq = <0x0f>;
			non-removable;
			max-frequency = <0x17d7840>;
			pinctrl-names = "default";
		};

		nand-controller@1c03000 {
			compatible = "allwinner,sun4i-a10-nand";
			clocks = <0x02 0x20 0x02 0x3f>;
			clock-names = "ahb", "mod";
			status = "okay";
			#address-cells = <0x01>;
			interrupts = <0x25>;
			#size-cells = <0x00>;
			dma-names = "rxtx";
			phandle = <0x2c>;
			reg = <0x1c03000 0x1000>;
			pinctrl-0 = <0x05 0x06 0x07>;
			dmas = <0x04 0x01 0x03>;
			pinctrl-names = "default";

			nand@0 {
				allwinner,rb = <0x00>;
				nand-on-flash-bbt;
				#address-cells = <0x02>;
				#size-cells = <0x02>;
				nand-ecc-maximize;
				reg = <0x00>;
				nand-ecc-mode = "hw";

				partitions {
					compatible = "fixed-partitions";
					#address-cells = <0x02>;
					#size-cells = <0x02>;

					partition@1000000 {
						label = "rootfs";
						reg = <0x00 0x1000000 0x01 0xff000000>;
						slc-mode;
					};

					partition@0 {
						label = "SPL";
						reg = <0x00 0x00 0x00 0x400000>;
					};

					partition@400000 {
						label = "SPL.backup";
						reg = <0x00 0x400000 0x00 0x400000>;
					};

					partition@800000 {
						label = "U-Boot";
						reg = <0x00 0x800000 0x00 0x400000>;
					};

					partition@c00000 {
						label = "env";
						reg = <0x00 0xc00000 0x00 0x400000>;
					};
				};
			};
		};

		interrupt-controller@1c20400 {
			compatible = "allwinner,sun4i-a10-ic";
			#interrupt-cells = <0x01>;
			phandle = <0x01>;
			reg = <0x1c20400 0x400>;
			interrupt-controller;
		};

		mdio@1c0b080 {
			compatible = "allwinner,sun4i-a10-mdio";
			status = "disabled";
			#address-cells = <0x01>;
			#size-cells = <0x00>;
			phandle = <0x31>;
			reg = <0x1c0b080 0x14>;
		};

		mmc@1c11000 {
			compatible = "allwinner,sun5i-a13-mmc";
			clocks = <0x02 0x1f 0x02 0x42>;
			clock-names = "ahb", "mmc";
			status = "disabled";
			#address-cells = <0x01>;
			interrupts = <0x22>;
			#size-cells = <0x00>;
			phandle = <0x37>;
			reg = <0x1c11000 0x1000>;
		};

		ethernet@1c0b000 {
			compatible = "allwinner,sun4i-a10-emac";
			clocks = <0x02 0x22>;
			status = "disabled";
			interrupts = <0x37>;
			allwinner,sram = <0x09 0x01>;
			phandle = <0x30>;
			reg = <0x1c0b000 0x1000>;
		};

		usb@1c14400 {
			compatible = "allwinner,sun5i-a13-ohci", "generic-ohci";
			clocks = <0x02 0x4c 0x02 0x19>;
			phy-names = "usb";
			status = "okay";
			interrupts = <0x28>;
			phandle = <0x3a>;
			phys = <0x10 0x01>;
			reg = <0x1c14400 0x100>;
		};

		system-control@1c00000 {
			compatible = "allwinner,sun5i-a13-system-control";
			ranges;
			#address-cells = <0x01>;
			#size-cells = <0x01>;
			reg = <0x1c00000 0x30>;

			sram@10000 {
				compatible = "mmio-sram";
				ranges = <0x00 0x10000 0x1000>;
				#address-cells = <0x01>;
				#size-cells = <0x01>;
				phandle = <0x2a>;
				reg = <0x10000 0x1000>;

				sram-section@0 {
					compatible = "allwinner,sun5i-a13-sram-d", "allwinner,sun4i-a10-sram-d";
					status = "okay";
					phandle = <0x11>;
					reg = <0x00 0x1000>;
				};
			};

			sram@0 {
				compatible = "mmio-sram";
				ranges = <0x00 0x00 0xc000>;
				#address-cells = <0x01>;
				#size-cells = <0x01>;
				phandle = <0x29>;
				reg = <0x00 0xc000>;

				sram-section@8000 {
					compatible = "allwinner,sun5i-a13-sram-a3-a4", "allwinner,sun4i-a10-sram-a3-a4";
					status = "disabled";
					phandle = <0x09>;
					reg = <0x8000 0x4000>;
				};
			};

			sram@1d00000 {
				compatible = "mmio-sram";
				ranges = <0x00 0x1d00000 0xd0000>;
				#address-cells = <0x01>;
				#size-cells = <0x01>;
				phandle = <0x2b>;
				reg = <0x1d00000 0xd0000>;

				sram-section@0 {
					compatible = "allwinner,sun5i-a13-sram-c1", "allwinner,sun4i-a10-sram-c1";
					phandle = <0x0c>;
					reg = <0x00 0x80000>;
				};
			};
		};

		dram-controller@1c01000 {
			#interconnect-cells = <0x01>;
			compatible = "allwinner,sun5i-a13-mbus";
			clocks = <0x02 0x63>;
			#address-cells = <0x01>;
			#size-cells = <0x01>;
			phandle = <0x20>;
			reg = <0x1c01000 0x1000>;
			dma-ranges = <0x00 0x40000000 0x20000000>;
		};

		spi@1c05000 {
			compatible = "allwinner,sun4i-a10-spi";
			clocks = <0x02 0x24 0x02 0x45>;
			clock-names = "ahb", "mod";
			status = "disabled";
			#address-cells = <0x01>;
			interrupts = <0x0a>;
			#size-cells = <0x00>;
			dma-names = "rx", "tx";
			phandle = <0x2d>;
			reg = <0x1c05000 0x1000>;
			dmas = <0x04 0x01 0x1b 0x04 0x01 0x1a>;
		};

		gpu@1c40000 {
			compatible = "allwinner,sun4i-a10-mali", "arm,mali-400";
			clocks = <0x02 0x31 0x02 0x62>;
			resets = <0x02 0x09>;
			clock-names = "bus", "core";
			interrupts = <0x45 0x46 0x47 0x48 0x49>;
			assigned-clock-rates = <0x1312d000>;
			assigned-clocks = <0x02 0x62>;
			phandle = <0x5f>;
			operating-points-v2 = <0x6a>;
			reg = <0x1c40000 0x10000>;
			interrupt-names = "gp", "gpmmu", "pp0", "ppmmu0", "pmu";
		};

		lradc@1c22800 {
			compatible = "allwinner,sun4i-a10-lradc-keys";
			status = "disabled";
			interrupts = <0x1f>;
			phandle = <0x4b>;
			reg = <0x1c22800 0x100>;
		};

		i2c@1c2b400 {
			compatible = "allwinner,sun4i-a10-i2c";
			clocks = <0x02 0x3a>;
			status = "okay";
			#address-cells = <0x01>;
			interrupts = <0x09>;
			#size-cells = <0x00>;
			phandle = <0x5d>;
			reg = <0x1c2b400 0x400>;
			pinctrl-0 = <0x1f>;
			pinctrl-names = "default";

			gpio@38 {
				compatible = "nxp,pcf8574a";
				gpio-controller;
				#interrupt-cells = <0x02>;
				interrupt-parent = <0x12>;
				interrupts = <0x06 0x00 0x02>;
				phandle = <0x5e>;
				reg = <0x38>;
				#gpio-cells = <0x02>;
				interrupt-controller;
			};
		};

		phy@1c13400 {
			compatible = "allwinner,sun5i-a13-usb-phy";
			clocks = <0x02 0x4d>;
			resets = <0x02 0x00 0x02 0x01>;
			reg-names = "phy_ctrl", "pmu1";
			clock-names = "usb_phy";
			status = "okay";
			phandle = <0x10>;
			usb0_id_det-gpios = <0x12 0x06 0x02 0x00>;
